window.TOURIM_POLICY_DATA = {"title": "TOURIM Combined Policy Manual", "tagline": "See the world, Feel with TOURIM", "effectiveDate": "13 June 2026", "version": "Policy Version 1.0", "source": "TOURIM_Combined_Policy_Manual.pdf", "contact": {"email": "owner.tourim@gmail.com", "phone": "7384732179 / 8972076635", "address": "Ashokenagar Kachua More, North 24 Parganas, West Bengal, 743272", "website": "Official TOURIM website / current domain"}, "metadata": [{"label": "Business / Brand Name", "value": "TOURIM"}, {"label": "Tagline", "value": "See the world, Feel with TOURIM"}, {"label": "Business Activity", "value": "Domestic and international tour package planning, booking coordination and travel support"}, {"label": "Office Address", "value": "Ashokenagar Kachua More, North 24 Parganas, West Bengal, 743272"}, {"label": "Authorized Representative", "value": "Aunkan Saha, Founder & Business Head"}, {"label": "Effective Date", "value": "13 June 2026"}, {"label": "Version", "value": "Policy Version 1.0"}], "contents": [{"section": "1", "title": "Purpose, Scope and Business Role", "anchor": "purpose-scope-and-business-role"}, {"section": "2", "title": "Privacy Policy", "anchor": "privacy-policy"}, {"section": "3", "title": "Booking Terms & Conditions", "anchor": "booking-terms-and-conditions"}, {"section": "4", "title": "Payment Policy", "anchor": "payment-policy"}, {"section": "5", "title": "Cancellation, Refund and Last Moment Cancellation Policy", "anchor": "cancellation-refund-and-last-moment-cancellation-policy"}, {"section": "6", "title": "Travel Safety, Accident, Medical Emergency and Insurance Policy", "anchor": "travel-safety-accident-medical-emergency-and-insurance-policy"}, {"section": "7", "title": "Climate, Weather, Natural Calamity and Force Majeure Policy", "anchor": "climate-weather-natural-calamity-and-force-majeure-policy"}, {"section": "8", "title": "Theft, Loss, Damage and Personal Belongings Policy", "anchor": "theft-loss-damage-and-personal-belongings-policy"}, {"section": "9", "title": "Guest Conduct, Misbehaviour and Right to Refuse Service Policy", "anchor": "guest-conduct-misbehaviour-and-right-to-refuse-service-policy"}, {"section": "10", "title": "Vendor, Hotel, Vehicle, Activity and Third-Party Service Policy", "anchor": "vendor-hotel-vehicle-activity-and-third-party-service-policy"}, {"section": "11", "title": "Document, Visa, Permit and Government Approval Policy", "anchor": "document-visa-permit-and-government-approval-policy"}, {"section": "12", "title": "Complaint, Grievance and Dispute Resolution Policy", "anchor": "complaint-grievance-and-dispute-resolution-policy"}, {"section": "13", "title": "Customer Photo, Review, Testimonial and Marketing Consent Policy", "anchor": "customer-photo-review-testimonial-and-marketing-consent-policy"}, {"section": "14", "title": "Short Clauses for Quotation, Invoice and WhatsApp", "anchor": "short-clauses-for-quotation-invoice-and-whatsapp"}, {"section": "15", "title": "Customer Acceptance Declaration", "anchor": "customer-acceptance-declaration"}], "sections": [{"num": "1", "title": "Purpose, Scope and Business Role", "blocks": [{"type": "p", "text": "This Combined Policy Manual explains the privacy, booking, payment, cancellation, refund, safety, liability, guest conduct, vendor coordination and dispute policies followed by TOURIM. It is intended for customers, guests, vendors, hotels, transport partners, travel partners, internal team members and any authority reviewing TOURIM documents. TOURIM is a travel agency and tour coordination brand. TOURIM plans and coordinates travel packages and related travel services through hotels, transport vendors, airlines, railways, local operators, guides, activity providers, destination management companies and other third-party service providers. By submitting an enquiry, sharing personal details, making payment, confirming a booking, joining a tour, or using TOURIM services, the guest confirms that they have read, understood and accepted this policy."}, {"type": "h3", "num": "1.1", "text": "Important Definitions"}, {"type": "li", "text": "TOURIM / Company / We / Us means TOURIM and its authorized team, representatives and service coordinators."}, {"type": "li", "text": "Guest / Customer / Traveller means the person who submits an enquiry, confirms booking, makes payment, travels under a TOURIM package, or uses TOURIM services."}, {"type": "li", "text": "Third-party service provider means any hotel, homestay, resort, houseboat, airline, railway, transport vendor, local cab, guide, local operator, activity provider, visa consultant, insurance provider, payment gateway or destination partner."}, {"type": "li", "text": "Package means the written itinerary, inclusions, exclusions, price, terms and confirmed services issued by TOURIM."}, {"type": "li", "text": "Force majeure means circumstances beyond TOURIM direct control, including weather, natural calamity, road blockage, strike, government order, accident, pandemic, unrest, transport disruption, permit restriction and similar situations."}, {"type": "h3", "num": "1.2", "text": "Company Protection Principle"}, {"type": "p", "text": "TOURIM will make reasonable efforts to plan, coordinate and support the guest during the travel process. However, TOURIM shall not be treated as the owner/operator of hotels, vehicles, airlines, railways, government authorities, local operators or activity providers unless specifically mentioned in writing. Liability for third-party services remains subject to the respective service provider terms and applicable law. Only written inclusions mentioned in the final quotation, invoice, voucher or itinerary shall be treated as confirmed. Verbal discussions, informal messages or assumptions shall not be treated as confirmed services unless included in writing."}], "id": "purpose-scope-and-business-role"}, {"num": "2", "title": "Privacy Policy", "blocks": [{"type": "h3", "num": "2.1", "text": "Introduction"}, {"type": "p", "text": "TOURIM respects the privacy of every customer and traveller. This Privacy Policy explains how TOURIM collects, uses, stores, shares, protects and deletes personal information when a guest visits the website, submits an enquiry, requests a quotation, books a package, makes a payment, shares travel documents, communicates through phone/WhatsApp/email/social media, or uses any TOURIM service. This policy is drafted keeping in mind applicable Indian data protection and consumer protection principles. It is not a substitute for legal advice and should be reviewed by a professional before final publication."}, {"type": "h3", "num": "2.2", "text": "Information We May Collect"}, {"type": "li", "text": "Personal details such as name, phone number, WhatsApp number, email address, address, city, state, country, age, gender and emergency contact."}, {"type": "li", "text": "Travel and booking details such as destination, travel date, number of travellers, passenger names, age of travellers, room preference, meal preference, vehicle preference, tour type and special requests."}, {"type": "li", "text": "Identity and travel documents such as Aadhaar, PAN, passport, visa documents, photographs, ID proof, permits and other documents required for booking, hotel check-in, visa, insurance or government process."}, {"type": "li", "text": "Payment information such as transaction ID, UPI reference, payment screenshot, invoice details, advance amount, balance payment status, refund details and billing records. TOURIM does not ask for OTP, UPI PIN, card CVV or banking passwords."}, {"type": "li", "text": "Communication records such as phone call notes, WhatsApp chats, email messages, enquiry history, customer support messages, complaints, feedback and testimonials."}, {"type": "li", "text": "Website and technical data such as IP address, browser type, device information, page visits, time spent, cookie data, referral source and analytics data."}, {"type": "li", "text": "Marketing and social media data such as reviews, ratings, comments, campaign responses, social media interactions and consent for promotional updates."}, {"type": "h3", "num": "2.3", "text": "How Information Is Collected"}, {"type": "li", "text": "When the guest submits an enquiry form or booking form."}, {"type": "li", "text": "When the guest contacts TOURIM through phone, WhatsApp, email, Instagram, Facebook or other platforms."}, {"type": "li", "text": "When the guest requests quotation, customization, invoice, voucher or package confirmation."}, {"type": "li", "text": "When the guest makes payment or shares transaction proof."}, {"type": "li", "text": "When the guest sends travel documents, ID proof, passport, visa documents or permit-related documents."}, {"type": "li", "text": "When the guest subscribes to offers, newsletters, festive deals or package announcements."}, {"type": "li", "text": "When the guest visits TOURIM website or interacts with TOURIM social media pages."}, {"type": "h3", "num": "2.4", "text": "Purpose of Using Information"}, {"type": "li", "text": "To prepare customized quotations, itineraries and travel packages."}, {"type": "li", "text": "To confirm hotels, flights, trains, vehicles, sightseeing, permits, visas, insurance, activities and other travel services."}, {"type": "li", "text": "To share vouchers, invoices, receipts, payment reminders, travel instructions, reporting time and emergency updates."}, {"type": "li", "text": "To manage cancellations, refunds, rescheduling, complaints and customer support."}, {"type": "li", "text": "To comply with tax, accounting, legal, hotel, transport, airline, immigration, permit, government and safety requirements."}, {"type": "li", "text": "To improve TOURIM website, packages, service quality, customer experience and internal business operations."}, {"type": "li", "text": "To send promotional offers, travel updates, festive deals and package announcements only where permitted or consented."}, {"type": "li", "text": "To prevent fraud, misuse, unauthorized transactions, false claims, chargebacks and security risks."}, {"type": "h3", "num": "2.5", "text": "Consent and Withdrawal"}, {"type": "p", "text": "By sharing details with TOURIM, submitting an enquiry, making payment, or confirming a booking, the guest authorizes TOURIM to process personal data for travel planning, booking coordination, customer support, legal compliance and related service delivery. The guest may withdraw consent for optional marketing communication at any time by contacting TOURIM. However, withdrawal of consent may affect the ability to provide services where data is necessary for hotel booking, transport booking, permits, visas, insurance, tickets, invoices, refunds, legal compliance or dispute resolution."}, {"type": "h3", "num": "2.6", "text": "Sharing of Information"}, {"type": "p", "text": "TOURIM may share limited necessary information with service providers and authorities only for travel service delivery, safety, legal compliance and customer support. Such parties may include:"}, {"type": "li", "text": "Hotels, resorts, homestays, houseboats and accommodation partners."}, {"type": "li", "text": "Airlines, railways, bus operators, transport vendors, cab drivers, tempo travellers and tour guides."}, {"type": "li", "text": "Destination management companies, activity providers, sightseeing vendors, cruise operators and local operators."}, {"type": "li", "text": "Visa consultants, insurance providers, forex partners, permit offices and government authorities where applicable."}, {"type": "li", "text": "Payment gateways, banks, accountants, invoicing tools, email services, cloud storage, hosting providers, analytics tools and CRM/communication systems."}, {"type": "li", "text": "Police, hospitals, emergency support teams, law enforcement, immigration, tourism authorities or regulatory bodies where legally required or needed for safety."}, {"type": "p", "text": "TOURIM does not sell personal data to third parties."}, {"type": "h3", "num": "2.7", "text": "WhatsApp, Phone, Email and Social Media Communication"}, {"type": "p", "text": "TOURIM may contact guests through WhatsApp, phone calls, SMS, email, Instagram, Facebook or other communication platforms for enquiry follow-up, booking updates, payment reminders, travel support, customer service and promotional offers. A guest may opt out of promotional messages by replying STOP or by contacting TOURIM directly."}, {"type": "h3", "num": "2.8", "text": "Cookies and Website Tracking"}, {"type": "p", "text": "TOURIM website may use cookies and similar tools to improve user experience, remember preferences, analyze traffic, measure campaign performance and improve website content. Guests may disable cookies through browser settings, but some website features may not work properly if cookies are disabled."}, {"type": "h3", "num": "2.9", "text": "Data Retention and Deletion"}, {"type": "p", "text": "TOURIM retains personal information only for as long as necessary for booking management, travel support, accounting, tax compliance, legal compliance, dispute resolution, fraud prevention, customer service and business record requirements. Travel documents and sensitive information are retained only as long as required for the purpose collected unless legal, accounting or dispute requirements require longer retention. Guests may request correction or deletion of personal data. TOURIM may refuse or delay deletion where retention is required for legal, tax, accounting, booking, refund, complaint, dispute or regulatory purposes."}, {"type": "h3", "num": "2.10", "text": "Data Security"}, {"type": "p", "text": "TOURIM uses reasonable administrative, technical and operational measures to protect personal information from unauthorized access, misuse, alteration, disclosure or loss. However, internet, WhatsApp, email and digital communication are not completely risk-free. Guests must share documents and payments only through official TOURIM channels."}, {"type": "h3", "num": "2.11", "text": "Children and Family Travellers"}, {"type": "p", "text": "For family travel, TOURIM may collect information of child travellers only from parents, guardians or authorized adult travellers for booking, hotel check-in, permits, visas, insurance, transport, safety or legal requirements. TOURIM does not knowingly collect children personal data for independent marketing purposes."}, {"type": "h3", "num": "2.12", "text": "International Travel and Cross-Border Sharing"}, {"type": "p", "text": "For international travel, guest information may be shared with overseas hotels, airlines, visa centres, immigration authorities, local destination partners, transport providers and travel service vendors outside India only as required to complete the travel arrangement."}, {"type": "h3", "num": "2.13", "text": "Guest Rights"}, {"type": "li", "text": "Request access to personal data shared with TOURIM."}, {"type": "li", "text": "Request correction of inaccurate or incomplete data."}, {"type": "li", "text": "Request deletion of personal data where legally permitted."}, {"type": "li", "text": "Withdraw consent for optional marketing communication."}, {"type": "li", "text": "Ask how personal data is being used for travel service delivery."}, {"type": "li", "text": "Raise a privacy grievance or complaint with TOURIM."}, {"type": "h3", "num": "2.14", "text": "Privacy During Accident, Theft or Complaint Handling"}, {"type": "p", "text": "During accidents, medical emergencies, theft, disputes, complaints or safety incidents, TOURIM may need to collect and share limited details such as guest name, phone number, ID proof, booking details, location, incident details, photos, medical information, police complaint copy or emergency contact information with hospitals, police, hotels, transport vendors, insurance providers, government authorities or family members. Such sharing will be done only for safety, support, legal compliance, claim processing or dispute handling."}, {"type": "h3", "num": "2.15", "text": "Contact for Privacy Requests"}, {"type": "p", "text": "Contact Field Details Business Name TOURIM Address Ashokenagar Kachua More, North 24 Parganas, West Bengal, 743272 Email owner.tourim@gmail.com Phone / WhatsApp 7384732179 / 8972076635 Website Official TOURIM website / current domain"}], "id": "privacy-policy"}, {"num": "3", "title": "Booking Terms & Conditions", "blocks": [{"type": "h3", "num": "3.1", "text": "TOURIM as Travel Coordinator"}, {"type": "p", "text": "TOURIM acts as a travel planner, package arranger and booking coordinator between the guest and third-party service providers such as hotels, transport vendors, airlines, railways, local operators, guides, activity providers, houseboats, restaurants, cruise operators and destination partners. TOURIM shall not be held responsible for service failure, delay, cancellation, strike, operational issue, quality issue, negligence or misconduct caused directly by any third-party vendor. TOURIM will provide reasonable assistance to resolve issues wherever possible."}, {"type": "h3", "num": "3.2", "text": "Written Confirmation Only"}, {"type": "p", "text": "Only written inclusions mentioned in the final quotation, invoice, confirmation voucher or itinerary shall be considered valid. Any verbal discussion, phone call, WhatsApp chat or informal conversation shall not be treated as a confirmed promise unless it is clearly included in the final written package confirmation."}, {"type": "h3", "num": "3.3", "text": "Inclusions and Exclusions"}, {"type": "p", "text": "Guests must carefully read inclusions, exclusions, hotel names/category, meal plan, vehicle type, sightseeing list, entry fees, permits, taxes and cancellation policy before making payment. Any service not specifically mentioned under Inclusions shall be treated as excluded and chargeable extra."}, {"type": "h3", "num": "3.4", "text": "Price Change and Availability"}, {"type": "p", "text": "Package prices are subject to availability and may change due to hotel rate changes, flight/train fare changes, fuel price increase, permit fee changes, tax changes, seasonal surcharge, peak-date surcharge, foreign exchange fluctuation, government fee change or vendor price revision. A quotation does not guarantee booking until advance payment is received and written confirmation is issued by TOURIM."}, {"type": "h3", "num": "3.5", "text": "Advance Payment and Booking Confirmation"}, {"type": "p", "text": "A booking shall be treated as confirmed only after TOURIM receives the required advance payment and issues written confirmation. If advance payment is delayed, hotels, rooms, vehicles, train seats, flight fares, package rates or availability may change. TOURIM shall not be responsible for price change or non-availability caused by payment delay from the guest."}, {"type": "h3", "num": "3.6", "text": "Balance Payment"}, {"type": "p", "text": "Guests must clear balance payment within the timeline mentioned in the quotation or invoice. If balance payment is not received on time, TOURIM reserves the right to hold, cancel or modify the booking without refunding any non-refundable advance already paid or committed to hotels, vendors, airlines, railways or local operators."}, {"type": "h3", "num": "3.7", "text": "Guest Document Responsibility"}, {"type": "p", "text": "Guests are fully responsible for providing correct names, ages, gender, ID proof, passport details, visa documents, photographs, PAN, Aadhaar, travel date, train/flight details and other required information. TOURIM shall not be responsible for ticket error, hotel check-in denial, permit rejection, visa rejection, immigration issue, boarding denial or travel disruption caused by incorrect, incomplete, expired, fake, mismatched or late-submitted documents."}, {"type": "h3", "num": "3.8", "text": "Missed Services Due to Guest Delay"}, {"type": "p", "text": "If any guest misses sightseeing, meals, transfers, train, flight, activity, check-in, permit timing or group departure due to late arrival, oversleeping, shopping delay, personal delay, illness, non-cooperation, document issue or any guest-side reason, TOURIM shall not be responsible. No refund shall be provided for unused services missed due to guest-side delay or personal reason."}, {"type": "h3", "num": "3.9", "text": "Group Tour Discipline"}, {"type": "p", "text": "For group tours, guests must follow fixed reporting time, departure time, sightseeing schedule, seat rotation, luggage rules, meal timing and instructions of the tour coordinator or driver. If any guest delays the group, creates disturbance, refuses to cooperate or affects other travellers experience, TOURIM reserves the right to continue the tour schedule without waiting for that guest."}, {"type": "h3", "num": "3.10", "text": "Health, Senior Citizen and Medical Disclosure"}, {"type": "p", "text": "Guests must inform TOURIM in advance about serious illness, pregnancy, disability, heart condition, breathing problem, allergy, mobility issue, senior citizen support requirement, special food requirement or any medical limitation. TOURIM shall not be responsible for health complications caused by non-disclosure of medical conditions or travelling against medical advice."}, {"type": "h3", "num": "3.11", "text": "Limitation of Liability"}, {"type": "p", "text": "To the maximum extent permitted by applicable law, TOURIM liability shall be limited only to the amount actually received by TOURIM for the affected service, excluding taxes, non-refundable vendor payments, government fees, payment gateway charges, convenience fees and services already used by the guest. TOURIM shall not be liable for indirect loss, emotional distress, loss of enjoyment, business loss, missed opportunity, personal expense or consequential damages caused by circumstances beyond TOURIM direct control."}, {"type": "h3", "num": "3.12", "text": "Policy Acceptance"}, {"type": "p", "text": "By confirming a booking, making payment or joining a TOURIM package, the guest confirms acceptance of TOURIM Privacy Policy, Booking Terms & Conditions, Payment Policy, Cancellation & Refund Policy, Travel Safety Policy, Guest Conduct Policy and all written package terms."}], "id": "booking-terms-and-conditions"}, {"num": "4", "title": "Payment Policy", "blocks": [{"type": "h3", "num": "4.1", "text": "Official Payment Channels Only"}, {"type": "p", "text": "All payments must be made only through official TOURIM payment channels shared by the authorized TOURIM team. Guests must verify the account name, UPI ID, payment link or QR code before making payment. TOURIM shall not be responsible for payments made to unauthorized accounts, fake profiles, fraudulent links, personal accounts of unauthorized persons or third parties pretending to represent TOURIM."}, {"type": "h3", "num": "4.2", "text": "Payment Safety"}, {"type": "li", "text": "TOURIM will never ask for OTP, UPI PIN, card PIN, card CVV, net banking password or sensitive banking credentials."}, {"type": "li", "text": "Guests must not share banking passwords, OTPs, UPI PINs or card details with anyone."}, {"type": "li", "text": "Payment confirmation is subject to actual credit in TOURIM account or confirmation from the payment gateway/bank."}, {"type": "li", "text": "Payment screenshots alone may not be treated as final proof if the amount is not credited."}, {"type": "h3", "num": "4.3", "text": "Invoice, Receipt and Tax"}, {"type": "p", "text": "TOURIM may issue invoice, receipt or payment acknowledgement after receiving payment. GST, taxes, government fees, convenience fees, gateway charges and service charges may apply as mentioned in the quotation or invoice. Tax components, once charged and reported, may not be refundable depending on applicable rules and accounting treatment."}, {"type": "h3", "num": "4.4", "text": "Partial Payment and Non-Payment"}, {"type": "p", "text": "Partial payment may be accepted only as booking advance. The guest must pay the remaining balance as per the due date. Non-payment or delayed payment may result in cancellation, hold, service denial, voucher hold, ticket hold, hotel release, vehicle release or additional charges. Non-refundable amounts paid or committed to vendors shall be borne by the guest."}, {"type": "h3", "num": "4.5", "text": "Chargeback and False Payment Dispute"}, {"type": "p", "text": "If a guest raises a false chargeback, wrongful refund claim, payment dispute or denial after receiving confirmation or services, TOURIM reserves the right to submit booking proof, invoice, communication records, vouchers, payment receipts, vendor confirmations and service proof to the bank, payment gateway, legal authority or dispute forum."}], "id": "payment-policy"}, {"num": "5", "title": "Cancellation, Refund and Last Moment Cancellation Policy", "blocks": [{"type": "h3", "num": "5.1", "text": "General Cancellation Rule"}, {"type": "p", "text": "Cancellation charges will apply as per TOURIM cancellation policy and also as per hotel, transport, airline, railway, cruise, activity provider, permit authority, local operator or vendor rules. Refund, if any, will be processed only after TOURIM receives the refundable amount from the concerned vendor or service provider. Convenience fees, payment gateway charges, GST, permit fees, ticket charges, service charges, planning charges, vendor cancellation charges and non-refundable advance payments may not be refundable."}, {"type": "h3", "num": "5.2", "text": "Meaning of Last Moment Cancellation"}, {"type": "p", "text": "Any cancellation requested close to the travel date shall be treated as last moment cancellation. For TOURIM, last moment cancellation includes cancellation within 15 days of journey date, within 7 days of journey date, within 72 hours of journey date, on the same day of journey, after tour starts or no-show."}, {"type": "h3", "num": "5.3", "text": "Last Moment Cancellation Charges"}, {"type": "p", "text": "Cancellation Timing Policy 15 to 8 days before travel A major portion of the package may become non-refundable because hotel, vehicle, train, flight, permit and vendor bookings are already blocked. Refund, if any, depends on vendor policy. 7 to 4 days before travel Treated as highly last moment cancellation. No cash refund is guaranteed. TOURIM may offer partial travel credit/voucher only if hotel/vendor allows adjustment. Within 72 hours of travel Treated as non-refundable. No refund shall be provided for hotel, transport, permit, sightseeing, guide, activity, meal plan, tickets or vendor-blocked services. Same-day cancellation / no-show Treated as 100% non-refundable. No refund or adjustment shall be provided if the guest does not report, refuses to travel, or cancels on journey date. After tour starts No refund for unused services. Extra cost for return transport, additional hotel, route change, medical support or personal arrangement shall be borne by the guest."}, {"type": "h3", "num": "5.4", "text": "Cancellation After Tour Starts"}, {"type": "p", "text": "If the guest cancels after the tour has started, leaves midway, skips sightseeing, refuses hotel stay, misses transfer or discontinues travel due to personal reasons, no refund shall be provided for unused services. Any extra cost for return transport, additional hotel, route change, medical emergency or personal arrangement shall be borne by the guest."}, {"type": "h3", "num": "5.5", "text": "Group Tour Last Moment Cancellation"}, {"type": "p", "text": "For group tours, last moment cancellation affects total group cost, hotel blocking, vehicle sharing, train/flight coordination and overall tour arrangement. Cancellation within 15 days of group departure may be treated as non-refundable unless TOURIM receives refund or adjustment from the concerned vendor. Seat replacement by another traveller may be allowed only with TOURIM written approval and subject to hotel, train, flight, permit and document rules."}, {"type": "h3", "num": "5.6", "text": "Flight, Train, Permit, Ticket and Activity Cancellation"}, {"type": "p", "text": "Flight tickets, train tickets, special permits, entry tickets, adventure activity tickets, event tickets, cruise tickets, ropeway tickets and government fees are subject to their own cancellation rules. TOURIM cannot guarantee refund for these services. Any refund will be processed only as per the concerned authority, airline, railway, vendor or service provider policy."}, {"type": "h3", "num": "5.7", "text": "Hotel and Transport Cancellation"}, {"type": "p", "text": "Hotels, houseboats, homestays, resorts, vehicles, tempo travellers, local cabs and transport vendors may charge full cancellation if cancelled at the last moment. If TOURIM has already paid or committed payment to vendors, the guest must accept the applicable deduction. Refund will be provided only if TOURIM receives refundable amount from the concerned vendor."}, {"type": "h3", "num": "5.8", "text": "Cancellation Due to Personal Reason"}, {"type": "p", "text": "No refund shall be guaranteed for cancellation due to personal reasons such as medical issue, family problem, office work, exam, change of mind, late arrival, wrong travel date, document issue, train/flight missed by guest, fear of weather without official cancellation, personal emergency or non-cooperation by traveller. TOURIM may try to support rescheduling or travel credit, but this is subject to vendor approval."}, {"type": "h3", "num": "5.9", "text": "Cancellation Due to Weather or Natural Calamity"}, {"type": "p", "text": "If the tour is affected due to heavy rain, landslide, snowfall, cyclone, flood, road blockage, government order, strike, curfew, permit restriction, transport restriction or natural calamity, TOURIM will try to provide the best possible alternative. However, refund is not guaranteed for services already booked, blocked, used or charged by vendors. Any extra cost for hotel extension, route change, vehicle change, food, permit or rescheduling shall be borne by the guest."}, {"type": "h3", "num": "5.10", "text": "Rescheduling Instead of Cancellation"}, {"type": "p", "text": "For last moment cancellation, TOURIM may offer rescheduling only if hotels, transport vendors, airlines, railways, local operators and other service providers allow date change. Rescheduling charges, fare difference, hotel rate difference, transport difference, permit charges or vendor penalties shall be paid by the guest. Rescheduling is not guaranteed."}, {"type": "h3", "num": "5.11", "text": "Refund Timeline"}, {"type": "p", "text": "If any refund is approved, it will be processed only after TOURIM receives the refundable amount from the concerned hotel, vendor, airline, railway, transport provider or service partner. Refund processing may take 7 to 21 working days after confirmation from the vendor. Bank charges, payment gateway charges, GST, convenience fees, service charges and non-refundable vendor payments will be deducted."}, {"type": "h3", "num": "5.12", "text": "TOURIM Service Charge"}, {"type": "p", "text": "TOURIM planning, coordination, consultation, itinerary preparation, booking management and service charges are non-refundable once the booking is confirmed."}, {"type": "h3", "num": "5.13", "text": "Final Decision"}, {"type": "p", "text": "In case of last moment cancellation, TOURIM decision will be based on vendor policies, booking status, payment status, travel date and actual loss already incurred. TOURIM will try to support the guest, but the company shall not be liable to bear loss caused by guest-side cancellation."}], "id": "cancellation-refund-and-last-moment-cancellation-policy"}, {"num": "6", "title": "Travel Safety, Accident, Medical Emergency and Insurance Policy", "blocks": [{"type": "h3", "num": "6.1", "text": "Accident, Injury and Medical Emergency"}, {"type": "p", "text": "TOURIM tries to arrange safe and reliable travel services. However, travel involves unavoidable risks including road accidents, medical emergencies, injuries, slips, falls, adventure activity risks, vehicle breakdowns, illness, food sensitivity, altitude sickness or unexpected incidents during the tour. TOURIM shall not be held responsible for any accident, injury, death, physical harm, medical emergency, hospital expense, personal negligence, risky activity or damage caused due to circumstances beyond TOURIM direct control. In an emergency, TOURIM will provide reasonable assistance such as contacting local support, hotel, driver, hospital, police, ambulance, vendor or guest family members. However, all medical expenses, hospital charges, emergency transport charges, medicine costs, rescue charges and other related costs shall be borne by the guest unless covered by travel insurance."}, {"type": "h3", "num": "6.2", "text": "Guest Medical Responsibility"}, {"type": "li", "text": "Guests must carry required medicines, prescriptions, emergency contacts and valid ID proof."}, {"type": "li", "text": "Guests with serious medical conditions must consult a doctor before travel."}, {"type": "li", "text": "Guests must disclose medical limitations, allergies, pregnancy, mobility issues or senior citizen support needs before booking."}, {"type": "li", "text": "TOURIM shall not be responsible for health complications caused by non-disclosure or travel against medical advice."}, {"type": "h3", "num": "6.3", "text": "Adventure Activity Risk"}, {"type": "p", "text": "Activities such as river rafting, paragliding, skiing, scuba diving, snorkeling, trekking, horse riding, camel safari, jeep safari, boating, ropeway, ATV, snow activities, water sports or adventure tours involve risk. Guests participate in such activities at their own risk and must follow local operator safety instructions. TOURIM shall not be liable for accident, injury, cancellation, delay or safety failure caused by the activity operator."}, {"type": "h3", "num": "6.4", "text": "Travel Insurance Recommendation"}, {"type": "p", "text": "TOURIM strongly recommends every traveller to purchase suitable travel insurance before the tour, especially for medical emergency, accident, baggage loss, trip cancellation, flight delay, theft, emergency evacuation and international travel risk. If the guest chooses not to purchase travel insurance, the guest accepts full responsibility for any uncovered loss, expense or emergency cost."}], "id": "travel-safety-accident-medical-emergency-and-insurance-policy"}, {"num": "7", "title": "Climate, Weather, Natural Calamity and Force Majeure Policy", "blocks": [{"type": "p", "text": "TOURIM is not responsible for tour disruption, delay, route change, cancellation, extra stay, missed sightseeing, missed transport or additional expense caused by weather, climate, natural calamity or force majeure situations."}, {"type": "h3", "num": "7.1", "text": "Examples of Force Majeure"}, {"type": "li", "text": "Heavy rain, flood, snowfall, landslide, storm, cyclone, earthquake, road blockage or natural disaster."}, {"type": "li", "text": "Political unrest, strike, curfew, traffic restriction, local union restriction or public disturbance."}, {"type": "li", "text": "Government order, permit restriction, forest/army/border restriction, police instruction or destination closure."}, {"type": "li", "text": "Flight delay, train delay, vehicle restriction, airport closure, railway disruption or transport breakdown."}, {"type": "li", "text": "Pandemic, epidemic, health advisory, safety advisory or emergency situation beyond TOURIM control."}, {"type": "h3", "num": "7.2", "text": "Alternative Arrangements"}, {"type": "p", "text": "If any sightseeing, transfer, hotel stay, activity or route is affected due to weather, climate, natural calamity, road closure or government restriction, TOURIM will try to provide the best possible alternative arrangement. However, any extra cost for additional hotel stay, vehicle, food, permit, transport, route change or rescheduling shall be paid by the guest."}, {"type": "h3", "num": "7.3", "text": "Refund Limitation"}, {"type": "p", "text": "No refund shall be guaranteed for unused services affected by weather, climate, natural calamity, road closure, local restriction, government order or circumstances beyond TOURIM control. Refund, if any, will depend on actual vendor refund received by TOURIM."}], "id": "climate-weather-natural-calamity-and-force-majeure-policy"}, {"num": "8", "title": "Theft, Loss, Damage and Personal Belongings Policy", "blocks": [{"type": "h3", "num": "8.1", "text": "Guest Responsibility"}, {"type": "p", "text": "Guests are fully responsible for their personal belongings during the tour, including luggage, mobile phones, cash, jewellery, camera, documents, passport, ID proof, tickets, cards, gadgets and valuable items. TOURIM shall not be responsible for theft, loss, misplacement, damage or disappearance of personal belongings from hotels, vehicles, tourist spots, restaurants, airports, railway stations, public places or during transfers."}, {"type": "h3", "num": "8.2", "text": "Assistance in Case of Theft or Loss"}, {"type": "p", "text": "In case of theft or loss, TOURIM may assist the guest in contacting the hotel, driver, local vendor, police station or relevant authority. Recovery of lost items is not guaranteed and TOURIM shall not be liable to compensate the guest for such loss."}, {"type": "h3", "num": "8.3", "text": "Safe Travel Advice"}, {"type": "li", "text": "Do not carry unnecessary valuables during sightseeing."}, {"type": "li", "text": "Keep important documents, cash, cards and expensive items with yourself."}, {"type": "li", "text": "Use hotel lockers where available, but understand that locker usage is subject to hotel rules."}, {"type": "li", "text": "Immediately report loss or theft to TOURIM, hotel, driver and local police where required."}, {"type": "h3", "num": "8.4", "text": "Damage Caused by Guest"}, {"type": "p", "text": "Any damage caused by the guest to hotel rooms, vehicles, houseboats, homestays, restaurants, public property, equipment or vendor property shall be the full responsibility of the guest. The guest must directly pay the damage amount, penalty, repair cost, cleaning charge, replacement cost or compensation demanded by the concerned hotel, vendor, driver or authority. TOURIM shall not be liable for such damage or penalty."}], "id": "theft-loss-damage-and-personal-belongings-policy"}, {"num": "9", "title": "Guest Conduct, Misbehaviour and Right to Refuse Service Policy", "blocks": [{"type": "h3", "num": "9.1", "text": "Expected Behaviour"}, {"type": "p", "text": "All guests are expected to behave respectfully with TOURIM management, staff, drivers, hotel staff, guides, vendors, co-travellers, local people and government officials during the tour."}, {"type": "h3", "num": "9.2", "text": "Zero-Tolerance Conduct"}, {"type": "li", "text": "Abusive language, threats, harassment or physical violence."}, {"type": "li", "text": "Intoxicated misbehaviour or public nuisance."}, {"type": "li", "text": "Damage to hotel, vehicle, vendor or public property."}, {"type": "li", "text": "Non-cooperation, refusal to follow safety instructions or creating disturbance during the tour."}, {"type": "li", "text": "Disrespectful behaviour with female staff, female guests, children, senior citizens or local people."}, {"type": "li", "text": "Illegal activity, restricted area violation, permit violation or possession/use of illegal items."}, {"type": "li", "text": "Fraud, fake documents, non-payment, false complaint, false review or wrongful claim."}, {"type": "h3", "num": "9.3", "text": "Action by TOURIM"}, {"type": "p", "text": "If any guest misbehaves with TOURIM management, staff, vendors, drivers, hotel partners or other travellers, TOURIM reserves the right to take necessary action including warning the guest, stopping service support, removing the guest from the tour, informing local authorities, cancelling remaining services, refusing future bookings or taking legal action. In such cases, no refund shall be provided for unused services, and any additional cost, penalty, property damage, police matter, hotel fine, vehicle damage or legal expense shall be borne by the guest."}, {"type": "h3", "num": "9.4", "text": "Alcohol, Illegal Items and Prohibited Activities"}, {"type": "p", "text": "Guests must follow all local laws and destination rules. TOURIM shall not be responsible for any issue arising from alcohol misuse, drugs, illegal items, public nuisance, restricted area violation, permit violation or unlawful activity by the guest. If a guest is detained, fined, questioned or penalized by police, hotel, airport, railway, immigration, forest department, army, border authority or any government body, the guest shall be solely responsible."}, {"type": "h3", "num": "9.5", "text": "Right to Refuse Service"}, {"type": "p", "text": "TOURIM reserves the right to refuse booking or discontinue service for any guest involved in abusive behaviour, fraud, non-payment, fake documents, illegal activity, harassment, property damage, repeated policy violation or misbehaviour with TOURIM team, vendors, drivers, hotels or co-travellers."}], "id": "guest-conduct-misbehaviour-and-right-to-refuse-service-policy"}, {"num": "10", "title": "Vendor, Hotel, Vehicle, Activity and Third-Party Service Policy", "blocks": [{"type": "h3", "num": "10.1", "text": "Third-Party Service Dependency"}, {"type": "p", "text": "Travel packages depend on multiple third-party service providers. TOURIM coordinates these services but does not directly control every hotel, vehicle, driver, airline, train, activity operator, government authority, local union, guide, restaurant or destination partner."}, {"type": "h3", "num": "10.2", "text": "Hotel Check-in and Room Policy"}, {"type": "p", "text": "Hotel check-in and check-out timings are fixed by the hotel. Early check-in, late check-out, room upgrade, specific floor, specific view, adjacent rooms, honeymoon decoration, extra bed, heater, AC, lift, balcony or room preference is subject to hotel availability and may be chargeable. TOURIM can request these facilities but cannot guarantee them unless confirmed in writing by the hotel and included in the package."}, {"type": "h3", "num": "10.3", "text": "Vehicle and Transport Policy"}, {"type": "p", "text": "Vehicles are provided as per itinerary and point-to-point sightseeing plan. Vehicle is not available for personal use, late-night use, market visits, extra sightseeing, route deviation or additional transfers unless mentioned in the package. In hills, remote areas, snowfall zones, narrow roads or restricted routes, vehicle type and movement may depend on local rules, weather, road condition, police instruction, union rules or permit restrictions."}, {"type": "h3", "num": "10.4", "text": "Local Rules and Route Restrictions"}, {"type": "p", "text": "Some destinations follow local transport union rules, restricted entry timings, parking restrictions, permit limitations, environmental rules or government orders. TOURIM shall not be responsible if routes, vehicles or sightseeing points are changed or restricted due to such rules. Extra charges, if any, shall be borne by the guest."}, {"type": "h3", "num": "10.5", "text": "Vendor Failure"}, {"type": "p", "text": "If a vendor fails to deliver service, delays service, changes operational terms or cancels due to unavoidable reasons, TOURIM will try to arrange alternative support where possible. TOURIM shall not be liable for loss caused directly by third-party failure beyond TOURIM control, except to the extent of refund actually received from the concerned vendor for the affected service."}], "id": "vendor-hotel-vehicle-activity-and-third-party-service-policy"}, {"num": "11", "title": "Document, Visa, Permit and Government Approval Policy", "blocks": [{"type": "h3", "num": "11.1", "text": "Document Accuracy"}, {"type": "p", "text": "The guest must submit correct, complete, valid and timely documents for all travellers. Names, ages, gender, ID numbers, passport details, visa documents, photographs and other required information must match official documents. TOURIM shall not be responsible for errors, rejection, cancellation or travel disruption caused by incorrect or late documents provided by the guest."}, {"type": "h3", "num": "11.2", "text": "Visa, Permit and Approval"}, {"type": "p", "text": "Visa, permit, entry pass, immigration clearance, border permission, forest permission, restricted area permit and government approval are subject to the decision of the concerned authority. TOURIM may assist with documentation and coordination, but approval is not guaranteed. Rejection, delay, cancellation or additional documentation demand by any authority shall not be considered TOURIM fault."}, {"type": "h3", "num": "11.3", "text": "Boarding and Check-in"}, {"type": "p", "text": "Guests must carry original ID proof, tickets, vouchers, permits, passport, visa, insurance and required travel documents during the journey. TOURIM shall not be responsible for boarding denial, hotel check-in denial, permit denial or immigration issue if the guest fails to carry proper documents or violates rules."}], "id": "document-visa-permit-and-government-approval-policy"}, {"num": "12", "title": "Complaint, Grievance and Dispute Resolution Policy", "blocks": [{"type": "h3", "num": "12.1", "text": "Complaint Reporting Timeline"}, {"type": "p", "text": "Any complaint regarding hotel, vehicle, driver, food, sightseeing, service or vendor issue must be reported to TOURIM immediately during the tour. If the guest does not report the issue during the tour and raises it only after completion, TOURIM may not be able to verify or resolve the matter. Post-tour complaints must be submitted in writing within 48 hours of tour completion."}, {"type": "h3", "num": "12.2", "text": "Evidence and Verification"}, {"type": "p", "text": "Guests should provide booking details, photos, videos, bills, location, vendor name and clear explanation when raising a complaint. TOURIM may verify the matter with vendors, hotels, drivers, local operators and internal records before taking a decision."}, {"type": "h3", "num": "12.3", "text": "Resolution Process"}, {"type": "li", "text": "TOURIM will acknowledge the complaint and collect relevant facts."}, {"type": "li", "text": "TOURIM will coordinate with the concerned vendor or internal team."}, {"type": "li", "text": "Where possible, TOURIM may offer correction, support, alternative arrangement, partial adjustment or written explanation."}, {"type": "li", "text": "Refund or compensation is not automatic and depends on actual service issue, evidence, vendor policy and amount received from vendor if applicable."}, {"type": "h3", "num": "12.4", "text": "Jurisdiction"}, {"type": "p", "text": "Any dispute arising from TOURIM bookings, services, payments, cancellations or travel arrangements shall first be attempted to be resolved through mutual discussion. If legal action is required, the matter shall be subject to the jurisdiction of the courts/forums having authority over North 24 Parganas, West Bengal, unless otherwise required by applicable law."}], "id": "complaint-grievance-and-dispute-resolution-policy"}, {"num": "13", "title": "Customer Photo, Review, Testimonial and Marketing Consent Policy", "blocks": [{"type": "p", "text": "TOURIM may request consent to use tour photos, group photos, customer feedback, testimonials and travel videos for promotional purposes, including website, social media, brochures, posters and marketing creatives. If any guest does not want their photo, video, review or testimonial to be used, they must inform TOURIM in writing. TOURIM will make reasonable efforts to avoid using or remove such content from future marketing materials. Already printed or published materials may take time to update depending on the platform and format. TOURIM shall not use sensitive personal details, identity documents, passport information, payment proof or private complaint details for public marketing without permission."}], "id": "customer-photo-review-testimonial-and-marketing-consent-policy"}, {"num": "14", "title": "Short Clauses for Quotation, Invoice and WhatsApp", "blocks": [{"type": "h3", "num": "14.1", "text": "Main Short Clause for Quotation / Invoice"}, {"type": "p", "text": "By confirming this booking, the guest agrees to TOURIM Privacy Policy, Cancellation Policy, Travel Safety Policy, Guest Conduct Policy and Terms & Conditions. TOURIM acts as a travel coordinator between the guest and third-party vendors. TOURIM shall not be responsible for accident, injury, theft, loss of belongings, weather disruption, natural calamity, road blockage, government restriction, vendor failure, guest misconduct, wrong documents, visa/permit rejection, transport delay or any situation beyond TOURIM direct control. Any extra cost arising from such situations shall be borne by the guest."}, {"type": "h3", "num": "14.2", "text": "Last Moment Cancellation Short Clause"}, {"type": "p", "text": "Last moment cancellation within 15 days of travel may attract heavy cancellation charges. Cancellation within 7 days, within 72 hours, same-day cancellation, no-show or cancellation after tour starts shall be treated as non-refundable. Refund, if any, will depend strictly on hotel, transport, airline, railway, permit, activity and vendor policies. TOURIM service charges, GST, payment gateway charges, convenience fees and non-refundable vendor payments are not refundable. Any extra cost due to cancellation, rescheduling, route change or personal reason shall be borne by the guest."}, {"type": "h3", "num": "14.3", "text": "Very Short WhatsApp Cancellation Note"}, {"type": "p", "text": "Cancellation Note: Last moment cancellation within 15 days of travel may be partially or fully non-refundable. Cancellation within 7 days / 72 hours / same-day / no-show will be treated as non-refundable. Refund, if any, depends only on hotel/vendor/transport/airline policy. TOURIM service charge, GST, gateway charges and vendor cancellation charges are non-refundable."}, {"type": "h3", "num": "14.4", "text": "Payment Safety Short Note"}, {"type": "p", "text": "Payment Safety: Please make payment only to official TOURIM payment channels. TOURIM never asks for OTP, UPI PIN, card PIN, CVV or banking password. TOURIM will not be responsible for payments made to fake links, unauthorized accounts or third parties pretending to represent TOURIM."}], "id": "short-clauses-for-quotation-invoice-and-whatsapp"}, {"num": "15", "title": "Customer Acceptance Declaration", "blocks": [{"type": "p", "text": "By signing, confirming over WhatsApp/email, making payment, or joining the tour, the guest confirms that they have read and accepted this TOURIM Combined Policy Manual, including privacy, payment, cancellation, refund, safety, liability, guest conduct, vendor and dispute terms. Acceptance Field Details Guest Name ____________________________________________ Booking / Package Name ____________________________________________ Travel Date ____________________________________________ Phone / WhatsApp ____________________________________________ Email ____________________________________________ Signature / Digital Confirmation ____________________________________________ Date ____________________________________________ Company Contact TOURIM Contact Field Details Business Name TOURIM Address Ashokenagar Kachua More, North 24 Parganas, West Bengal, 743272 Official Email owner.tourim@gmail.com Official Phone / WhatsApp 7384732179 / 8972076635 Website Official TOURIM website / current domain Authorized Representative Aunkan Saha, Founder & Business Head End of TOURIM Combined Policy Manual."}], "id": "customer-acceptance-declaration"}]};
